<script setup lang="ts">
import{describeLiveFailure}from'~/features/live-core/gateway';
useSeoMeta({title:'平台管理｜语赞心声'});const gateway=useEntryLiveGateway();const state=ref<'loading'|'ready'|'empty'|'gap'|'error'>('loading');const schools=ref<Record<string,unknown>[]>([]);const failure=ref<ReturnType<typeof describeLiveFailure>|null>(null);async function load(){state.value='loading';try{const response=await gateway.adminSchools();schools.value=response.data.items;state.value=schools.value.length?'ready':'empty'}catch(error){failure.value=describeLiveFailure(error);state.value=failure.value.code==='PERSISTENCE_PENDING'?'gap':'error'}}await load();
</script>
<template><section class="admin yx-shell" aria-labelledby="admin-title"><header><div><p class="yx-kicker">OPERATIONS · ADMIN</p><h1 id="admin-title">平台管理，<br>从真实持久化开始。</h1><p>页面沿用 VM A 的分区与状态表达，不采用其展示统计。</p></div><div class="terrain" aria-hidden="true"></div></header><section v-if="state==='loading'" class="state" aria-live="polite"><h2>正在验证管理数据能力……</h2></section><section v-else-if="state==='gap'" class="gap" role="status"><div class="gap__code">P2</div><div><p class="yx-kicker">{{failure?.code}}</p><h2>{{failure?.message}}</h2><p>管理页当前没有可依赖的持久化读写。学校数量、用户数量、活跃度和审批结果均不渲染。</p><dl><div><dt>后端范围</dt><dd>ADMIN_PERSISTENCE</dd></div><div><dt>当前动作</dt><dd>只读状态说明</dd></div><div><dt>写入能力</dt><dd>禁用</dd></div></dl></div></section><section v-else-if="state==='error'" class="state" role="alert"><p class="yx-kicker">{{failure?.code||failure?.kind}}</p><h2>{{failure?.message}}</h2><NuxtLink v-if="failure?.kind==='unauthenticated'" to="/login?redirect=/admin">重新登录</NuxtLink><NuxtLink v-else-if="failure?.kind==='permission'" to="/select-school">切换学校</NuxtLink><button v-else type="button" @click="load">重试</button></section><section v-else class="live"><p class="yx-kicker">LIVE RECORDS</p><h2>{{schools.length}} 条学校记录</h2><p v-if="state==='empty'">服务端返回空列表。</p><ol v-else><li v-for="(item,index) in schools" :key="String(item.id||index)"><b>{{String(index+1).padStart(2,'0')}}</b><code>{{String(item.id||'无标识')}}</code><span>{{String(item.name||'未命名学校')}}</span></li></ol></section><footer><button disabled type="button">创建学校 · persistence pending</button><button disabled type="button">邀请用户 · persistence pending</button><p>按钮禁用不是视觉演示，而是当前后端事实。</p></footer></section></template>
